import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh, Color } from 'three/webgpu';
import { texture, uv, hash, vec3, mix, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.userData.handlers = {};

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10',
  };

  // --- main texture plane (atlas 0,0,512,320) ---
  const planeGeo = new PlaneGeometry(1.0, 1.0 * (320 / 512));
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const grain = hash(uv().mul(2048.0)).sub(0.5).mul(0.025);
  const baseColor = mix(vec3(0.043, 0.043, 0.063), vec3(0.086, 0.086, 0.114), uv().y);
  material.colorNode = mix(baseColor, texture(null, uv()), 1.0).add(vec3(grain, grain, grain));

  let texLoaded = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearMipmapLinearFilter;
      tex.magFilter = THREE.LinearFilter;
      // atlas region 0,0,512,320 — map UVs to that sub-rect (assume 512x320 atlas == full image)
      const w = 512, h = 320;
      tex.matrixAutoUpdate = false;
      tex.matrix.setUvTransform(0, 0, 1, 1, 0, 0, 0);
      material.map = tex;
      material.colorNode = texture(tex, uv()).add(vec3(grain, grain, grain));
      material.needsUpdate = true;
      texLoaded = tex;
    });
  } else {
    material.colorNode = baseColor.add(vec3(grain, grain, grain));
  }

  const plane = new Mesh(planeGeo, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- backing panel for engineered gradient + depth ---
  const backGeo = new PlaneGeometry(1.1, 1.1 * (320 / 512));
  const backMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.95 });
  const g1 = vec3(0.043, 0.043, 0.063); // surface
  const g2 = vec3(0.086, 0.086, 0.114); // ink-ish
  backMat.colorNode = mix(g1, g2, uv().mul(1.0).sub(vec3(0,0,0)).y);
  const back = new Mesh(backGeo, backMat);
  back.position.z = -0.04;
  group.add(back);

  // --- accent edge stripe (signal red) along the bottom ---
  const edgeGeo = new PlaneGeometry(1.0, 0.02);
  const edgeMat = new MeshBasicNodeMaterial();
  edgeMat.colorNode = vec3(1.0, 0.165, 0.22); // #ff2a38
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -0.312, 0.001);
  group.add(edge);

  // faint highlight band to break flatness (per spec: subtle grain + engineered gradient)
  const sheenGeo = new PlaneGeometry(1.0, 0.5);
  const sheenMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.12 });
  sheenMat.colorNode = vec3(0.91, 0.925, 0.95);
  const sheen = new Mesh(sheenGeo, sheenMat);
  sheen.position.set(0, 0.08, 0.002);
  group.add(sheen);

  // --- position from config (adapter applies scenePosition, but set initial) ---
  const pos = config.scenePosition ?? config.intent?.scenePosition ?? { x: 3.2, y: -0.3, z: 0 };
  group.position.set(pos.x ?? 3.2, pos.y ?? -0.3, pos.z ?? 0);
  group.rotation.set(config.rotation?.x ?? 0, config.rotation?.y ?? 0, config.rotation?.z ?? 0);

  // entrance: rise-in settle (per animation vocabulary) — no primitives requested
  group.userData._gIn = gsap.from(group.position, {
    y: (pos.y ?? -0.3) + 0.4,
    duration: 0.7,
    ease: 'power3.out',
    overwrite: true,
  });
  group.userData._gAlpha = gsap.from(group, { scale: 0.96, duration: 0.9, ease: 'power4.out' });

  group.userData.cleanup = () => {
    if (group.userData._gIn) group.userData._gIn.kill();
    if (group.userData._gAlpha) group.userData._gAlpha.kill();
    planeGeo.dispose();
    backGeo.dispose();
    edgeGeo.dispose();
    sheenGeo.dispose();
    material.dispose();
    backMat.dispose();
    edgeMat.dispose();
    sheenMat.dispose();
    if (texLoaded) texLoaded.dispose();
  };

  return group;
}
